create schema if not exists controle;
create table controle.produto (sigla varchar(20) primary key, nome varchar(120) not null, ativo boolean not null default true);
create table controle.relatorio (codigo varchar(25) primary key, sigla_produto varchar(20) not null references controle.produto(sigla), nome varchar(160) not null, descricao varchar(500) not null, tempo_estimado_segundos integer not null check (tempo_estimado_segundos > 0), ativo boolean not null default true, check (codigo ~ '^[A-Z]{1,20}-[0-9]{4}$'));
create table controle.execucao (id uuid primary key, data_referencia date not null, codigo_relatorio varchar(25) not null references controle.relatorio(codigo), status varchar(40) not null, origem varchar(30) not null, iniciado_em timestamptz, finalizado_em timestamptz, duracao_segundos integer, tempo_estimado_segundos integer not null, unique (id, data_referencia, codigo_relatorio));
create table controle.execucao_vigente (data_referencia date not null, codigo_relatorio varchar(25) not null references controle.relatorio(codigo), execucao_id uuid not null, primary key (data_referencia, codigo_relatorio), foreign key (execucao_id, data_referencia, codigo_relatorio) references controle.execucao(id, data_referencia, codigo_relatorio));
create function controle.impede_mutacao_execucao() returns trigger language plpgsql as $$ begin raise exception 'execucao é append-only'; end; $$;
create trigger impede_update_execucao before update or delete on controle.execucao for each row execute function controle.impede_mutacao_execucao();
create table controle.artefato (id uuid primary key, execucao_id uuid not null references controle.execucao(id), localizacao text not null, expurgado_em timestamptz);
create table controle.auditoria (id uuid primary key, momento timestamptz not null, tipo varchar(60) not null, solicitante varchar(120), motivo varchar(500), correlation_id varchar(120), detalhes jsonb not null);
create table controle.download (id uuid primary key, codigo_relatorio varchar(25) not null, nome_relatorio varchar(160) not null, sigla_produto varchar(20) not null, data_referencia date not null, formato varchar(10) not null, usuario varchar(120) not null, momento timestamptz not null);
create table controle.relatorio_role (codigo_relatorio varchar(25) not null references controle.relatorio(codigo), role varchar(120) not null, primary key (codigo_relatorio, role));
